def decode(vals):
    result = []
    for v in vals:
        if v < 26:
            result.append(chr(ord('A') + v))
        else:
            result.append(chr(ord('a') + v - 26))
    return ''.join(result)

print("Modded decoded:", decode(modded))
print("Inverses decoded:", decode(inverses))

